<?php require "../config.php";if(!isset($_SESSION["user_id"])){header("Location: login.php");exit;}$s=$pdo->prepare("SELECT r.*,d.name dept,d.contact FROM emergency_reports r JOIN departments d ON d.id=r.department_id WHERE r.user_id=? ORDER BY r.created_at DESC");$s->execute([$_SESSION["user_id"]]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);?><!doctype html><html><head><title>Dashboard</title><link rel="stylesheet" href="../assets/style.css"></head><body><nav><div class="brand">🚨 SERP</div><div>Welcome, <?=htmlspecialchars($_SESSION["user_name"])?> <a href="logout.php">Logout</a></div></nav><div class="container"><h2>Citizen Dashboard</h2><div class="dashboard"><div class="stat"><b><?=count($rows)?></b><br>My Reports</div><div class="stat"><a class="btn" href="report.php">Report Emergency</a></div></div><h2>My Emergency Reports</h2><table class="table"><tr><th>ID</th><th>Type</th><th>Department</th><th>Location</th><th>Date</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=$r["type"]?></td><td><?=$r["dept"]?></td><td><?=$r["location"]?></td><td><?=$r["created_at"]?></td><td><?=$r["status"]?></td></tr><?php endforeach;?></table></div></body></html>